const output = [];
for (const item of $input.all()) {
  const binaries = item.binary || {};
  for (const [propertyName, binary] of Object.entries(binaries)) {
    const fileName = String(binary.fileName || propertyName);
    if (!fileName.toLowerCase().endsWith('.csv')) continue;
    output.push({ json: { sourceFile: fileName }, binary: { data: binary } });
  }
}
if (!output.length) throw new Error('Не найдено ни одного загруженного CSV-файла.');
return output;

function normalizedKey(value) {
  return String(value || '').replace(/^\uFEFF/, '').toLowerCase()
    .replace(/ё/g, 'е').replace(/[^a-zа-я0-9]+/g, '');
}
function firstByAliases(row, aliases) {
  const index = new Map(Object.entries(row || {})
    .map(([key, value]) => [normalizedKey(key), value]));
  for (const alias of aliases) {
    const value = index.get(normalizedKey(alias));
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}
const requests = [];
const seen = new Set();
for (const item of $input.all()) {
  const rows = Array.isArray(item.json) ? item.json : [item.json || {}];
  for (const row of rows) {
    const seldonId = String(firstByAliases(row, [
      'ID', 'SeldonID', 'seldon_id', 'seldonId', 'ИД', 'Идентификатор'
    ])).trim();
    if (!/^\d+$/.test(seldonId) || seen.has(seldonId)) continue;
    seen.add(seldonId);
    requests.push({
      seldonId,
      sourceStatus: String(firstByAliases(row, ['Статус тендера', 'Статус', 'tenderStatus'])).trim(),
      sourceReason: String(firstByAliases(row, ['Причина статуса', 'tenderStatusReason'])).trim(),
      sourceNote: String(firstByAliases(row, ['Примечание к статусу', 'tenderStatusNote'])).trim().slice(0, 4000),
      sourceFile: String(row.sourceFile || '').trim(),
    });
  }
}
if (!requests.length) throw new Error('В CSV не найдена колонка ID/SeldonID с числовыми идентификаторами.');
return [{ json: { requests, requestedCount: requests.length } }];

function number(value) {
  const parsed = Number(String(value ?? '').replace(/\s/g, '').replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
}
function money(value) {
  const text = String(value ?? '').toLowerCase().replace(/\u00A0/g, ' ');
  let multiplier = 1;
  if (/\bмлрд/.test(text)) multiplier = 1000000000;
  else if (/\bмлн/.test(text)) multiplier = 1000000;
  let cleaned = text.replace(/\s/g, '').replace(/[^0-9,.-]/g, '');
  const comma = cleaned.lastIndexOf(',');
  const dot = cleaned.lastIndexOf('.');
  if (comma >= 0 && dot >= 0) {
    const decimal = comma > dot ? ',' : '.';
    cleaned = cleaned.replace(decimal === ',' ? /\./g : /,/g, '').replace(decimal, '.');
  } else if (comma >= 0) cleaned = cleaned.replace(',', '.');
  const parsed = Number(cleaned);
  return Number.isFinite(parsed) ? parsed * multiplier : null;
}
const DOC_REASON = 'Оргвопросы. Отсутствует ТЗ / Нет документации / Некорректная ссылка';
const PRICE_REASON = 'Коммерческие условия. НМЦК менее 1 млн руб.';
const semanticReasons = [
  'Номенклатура. Поставка с работами',
  'Коммерческие условия. Консигнация / Хранение у Покупателя за счет Поставщика',
  'Номенклатура. Ремкомплект / ЗИП / Продукция по чертежу',
  'Коммерческие условия. Поставка в удаленные территории',
  'Номенклатура. Оборудование 35 кВ и выше',
  'Коммерческие условия. Оплата Покупателем после оплаты Генподрядчиком / Госзаказчиком',
  'Оргвопросы. Отказ организатора от проведения тендера',
];
const assessed = [];
for (const item of $input.all()) {
  const row = item.json || {};
  const issues = [];
  const add = (code, severity, message) => issues.push({ code, severity, message });
  if (!row.recordKey) add('JOB_NOT_FOUND', 'high', 'Seldon ID из CSV не найден в tender_autofill_jobs.');
  if (row.jobStatus === 'failed') add('JOB_FAILED', 'high', row.errorMessage || 'Job завершилась failed.');
  if (row.jobStatus === 'completed' && !row.hasResult) add('COMPLETED_WITHOUT_RESULT', 'high', 'Job completed, но result_json отсутствует.');
  if (row.sourceStatus && row.tenderStatus && row.sourceStatus !== row.tenderStatus) add('CSV_DB_STATUS_MISMATCH', 'medium', 'Статус в CSV отличается от последнего result_json.');
  if (row.sourceReason && row.tenderReason && row.sourceReason !== row.tenderReason) add('CSV_DB_REASON_MISMATCH', 'medium', 'Причина в CSV отличается от последнего result_json.');
  const total = number(row.productsTotal);
  const supplied = number(row.suppliedCount);
  const coverage = number(row.coveragePercent);
  if (total !== null && supplied !== null && total > 0 && coverage !== null) {
    const expected = Math.round((supplied / total) * 10000) / 100;
    if (Math.abs(expected - coverage) > 0.011) add('COVERAGE_ARITHMETIC_MISMATCH', 'high', 'coveragePercent не равен suppliedCount / productsTotal × 100.');
  }
  if (row.lotDivisible === true && total > 0) {
    const expectedApproved = supplied >= 1;
    if (Boolean(row.coverageApproved) !== expectedApproved) add('DIVISIBLE_LOT_RULE_MISMATCH', 'high', 'Для делимого лота достаточно одной поставляемой позиции.');
  }
  if (row.lotDivisible !== true && coverage !== null) {
    const expectedApproved = coverage >= 80;
    if (Boolean(row.coverageApproved) !== expectedApproved) add('INDIVISIBLE_LOT_RULE_MISMATCH', 'high', 'Для неделимого/неопределённого лота применяется coverage >= 80%.');
  }
  if ([row.sourceReason, row.tenderReason].includes(DOC_REASON)) {
    if (number(row.parsedDocumentCount) > 0 && row.documentationMissing !== true) {
      add('FALSE_DOCUMENTATION_REASON', 'high', 'Документы разобраны, но выбрана причина об их отсутствии.');
    } else {
      add('DOCUMENTATION_REJECTION_REVIEW', 'medium', 'Проверить отказ по документам по Seldon, скачиванию и парсингу.');
    }
  }
  if (row.tenderReason === PRICE_REASON && [1, 2].includes(number(row.reportId))) {
    const initial = money(row.initialPrice);
    if (initial !== null && initial >= 1000000) add('FALSE_REGULATED_PRICE_REASON', 'high', 'Для 223/44-ФЗ начальная цена не меньше 1 млн руб.');
  }
  if (row.tenderReason === PRICE_REASON && number(row.reportId) === 3) {
    if (row.priceEvaluationComplete !== true || row.supplyValueThresholdApplicable !== true || row.supplyValueHardReject !== true) {
      add('FALSE_COMMERCIAL_PRICE_REASON', 'high', 'Для коммерции причина цены требует полного расчёта Qdrant-цена × количество.');
    }
  }
  if (row.tenderStatus === 'Согласовано КУ ЦП' && number(row.hardReasonCount) > 0) add('APPROVED_WITH_HARD_REASONS', 'high', 'Тендер согласован при наличии детерминированных hardReasons.');
  if (row.tenderStatus === 'Отказано КУ ЦП' && !String(row.tenderReason || '').trim()) add('REJECTED_WITHOUT_REASON', 'high', 'Отказанный тендер не имеет причины статуса.');
  if (semanticReasons.includes(String(row.tenderReason || ''))) add('SEMANTIC_EVIDENCE_REVIEW', 'medium', 'Причина требует смысловой проверки evidence отдельным судьёй.');
  assessed.push({ json: {
    ...row,
    deterministicIssues: issues,
    deterministicCandidate: issues.length > 0,
    needsScout: true
  } });
}
return assessed;

const source = $('Подготовить запрос судье').item.json;
const response = $json || {};
let content = response.output
  ?? response.text
  ?? response.response
  ?? response.choices?.[0]?.message?.content
  ?? '';
if (Array.isArray(content)) content = content.map((part) => part?.text || part?.content || '').join('');
function parseJson(value) {
  if (value && typeof value === 'object') return value;
  const fence = String.fromCharCode(96).repeat(3);
  const sourceText = String(value || '').replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
  try { return JSON.parse(sourceText); } catch {}
  const start = sourceText.indexOf('{');
  const end = sourceText.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { return JSON.parse(sourceText.slice(start, end + 1)); } catch {}
  }
  return null;
}
const audit = parseJson(content);
const fallback = {
  verdict: 'needs_manual_review', originalResultCorrect: null, severity: 'high',
  summary: 'Ответ LLM-судьи не удалось разобрать как JSON.',
  suggestedStatus: null, suggestedReason: null,
  issues: [{
    code: 'AUDITOR_RESPONSE_PARSE_ERROR',
    message: 'LLM не вернул валидный JSON.',
    evidence: String(content || response.error?.message || '').slice(0, 1000)
  }]
};
return [{ json: {
  ...source.auditSeed,
  auditDetail: source.auditDetail,
  llmAudit: audit || fallback,
  auditorModel: response.model || 'deepseek/deepseek-v4-flash-0731',
  auditorRequestId: response.id || ''
} }];

function cell(value) {
  if (value === undefined || value === null) return '';
  if (Array.isArray(value)) return value.join(' | ');
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}
function escapeCsv(value) {
  const text = cell(value);
  return /[;"\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
function issueText(issues) {
  return (Array.isArray(issues) ? issues : [])
    .map((item) => [item.code, item.message, item.evidence].filter(Boolean).join(' — '))
    .join(' | ');
}
const rows = $input.all().map((item) => {
  const value = item.json || {};
  const audit = value.llmAudit || {};
  return {
    'Seldon ID': value.requestedSeldonId || value.auditDetail?.seldonId || '',
    'Record key': value.recordKey || value.auditDetail?.recordKey || '',
    'Report ID': value.reportId || value.auditDetail?.reportId || '',
    'Статус Worker': value.tenderStatus || '',
    'Причина Worker': value.tenderReason || '',
    'Примечание Worker': value.tenderNote || '',
    'Отобран по': Array.isArray(value.selectionReasons) ? value.selectionReasons.join(' | ') : '',
    'Первичный LLM: подозрение': value.scoutAudit?.suspicious,
    'Первичный LLM: нужна детальная проверка': value.scoutAudit?.requiresDetailedReview,
    'Первичный LLM: вывод': value.scoutAudit?.summary || '',
    'Первичный LLM: сигналы': Array.isArray(value.scoutAudit?.signals) ? value.scoutAudit.signals.join(' | ') : '',
    'Вердикт подробного аудитора': audit.verdict || 'needs_manual_review',
    'Результат Worker корректен': audit.originalResultCorrect,
    'Severity': audit.severity || 'medium',
    'Вывод аудитора': audit.summary || '',
    'Предлагаемый статус': audit.suggestedStatus || '',
    'Предлагаемая причина': audit.suggestedReason || '',
    'Детерминированные подозрения': issueText(value.deterministicIssues),
    'Замечания LLM-судьи': issueText(audit.issues),
    'Документов разобрано': value.parsedDocumentCount,
    'Товаров всего': value.productsTotal,
    'Поставляемых товаров': value.suppliedCount,
    'Coverage, %': value.coveragePercent,
    'Расчётная стоимость, руб.': value.supplyTotalPriceRub,
    'Модель аудитора': value.auditorModel || '',
    'Дата аудита': new Date().toISOString()
  };
});
const headers = Object.keys(rows[0] || { 'Результат': '' });
const lines = [headers.map(escapeCsv).join(';'),
  ...rows.map((row) => headers.map((key) => escapeCsv(row[key])).join(';'))];
const day = new Date().toISOString().slice(0, 10);
return [{ json: {
  csvText: '\uFEFF' + lines.join('\r\n'),
  fileName: 'tender_autofill_audit_' + day + '.csv',
  suspiciousCount: rows.length
} }];

function escapeCsv(value) {
  const text = String(value ?? '');
  return /[;"\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
}
const day = new Date().toISOString().slice(0, 10);
let headers;
let row;
if ($json.noIssues === true) {
  headers = ['Результат', 'Проверено тендеров', 'Дата аудита'];
  row = ['Подозрительных тендеров не найдено', $json.checkedCount || 0, new Date().toISOString()];
} else {
  headers = ['Seldon ID', 'Record key', 'Job status', 'Ошибка Worker', 'Статус Worker', 'Причина Worker', 'Вердикт аудитора', 'Severity', 'Детерминированные замечания', 'Дата аудита'];
  const issues = (Array.isArray($json.deterministicIssues) ? $json.deterministicIssues : [])
    .map((item) => [item.code, item.message].filter(Boolean).join(' — ')).join(' | ');
  const severity = (Array.isArray($json.deterministicIssues) ? $json.deterministicIssues : [])
    .some((item) => item.severity === 'high') ? 'high' : 'medium';
  row = [$json.requestedSeldonId || '', $json.recordKey || '', $json.jobStatus || '',
    $json.errorMessage || '', $json.tenderStatus || '', $json.tenderReason || '',
    'needs_manual_review', severity, issues, new Date().toISOString()];
}
return [{ json: {
  csvText: '\uFEFF' + [headers.map(escapeCsv).join(';'), row.map(escapeCsv).join(';')].join('\r\n'),
  fileName: 'tender_autofill_audit_' + day + '.csv',
  suspiciousCount: $json.noIssues === true ? 0 : 1
} }];

const seed = $('Подготовить первичный LLM-аудит').item.json.scoutSeed || {};
const response = $json || {};
let content = response.output ?? response.text ?? response.response ?? response.choices?.[0]?.message?.content ?? '';
if (Array.isArray(content)) content = content.map((part) => part?.text || part?.content || '').join('');
function parse(value) {
  if (value && typeof value === 'object') return value;
  const fence = String.fromCharCode(96).repeat(3);
  const text = String(value || '').replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'); const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) { try { return JSON.parse(text.slice(start, end + 1)); } catch {} }
  return null;
}
const parsed = parse(content);
const scoutAudit = parsed || {
  suspicious: true, requiresDetailedReview: true, confidence: 'low',
  summary: 'Ответ первичного аудитора не удалось разобрать; нужна подробная проверка.',
  signals: [String(content || response.error?.message || 'Пустой ответ').slice(0, 1000)],
  parseError: true
};
return [{ json: { ...seed, scoutAudit } }];

function yes(value) {
  return value === true || String(value ?? '').toLowerCase() === 'true';
}
const input = $input.all();
const selected = [];
for (const item of input) {
  const row = item.json || {};
  const scout = row.scoutAudit || {};
  const deterministic = row.deterministicCandidate === true || (Array.isArray(row.deterministicIssues) && row.deterministicIssues.length > 0);
  const llmSelected = yes(scout.suspicious) || yes(scout.requiresDetailedReview) || yes(scout.parseError);
  const operational = row.jobStatus === 'failed' || (row.jobStatus === 'completed' && !row.hasResult) || !row.recordKey;
  if (!deterministic && !llmSelected && !operational) continue;
  const selectionReasons = [];
  if (deterministic) selectionReasons.push('deterministic');
  if (llmSelected) selectionReasons.push('llm_scout');
  if (operational) selectionReasons.push('operational');
  selected.push({ json: {
    ...row,
    selectionReasons,
    needsLlm: Boolean(row.recordKey && row.hasResult)
  } });
}
if (!selected.length) return [{ json: {
  needsLlm: false, noIssues: true, checkedCount: input.length,
  message: 'Детерминированная проверка и первичный LLM-аудит не нашли кандидатов.'
} }];
